from pathlib import Path
import importlib.util
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('bounded_author',HERE.parent/'wirtschaft-e2-twenty-bilingual-positive-author-v1/author_candidate.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);m.OUT=HERE;m.REVIEW_ID='canonical-economics-e-company-twenty-positive-author-20261008-v1';m.REVIEWER='codex-economics-e-company-twenty-author-v1';m.ENTRIES=[]
def add(title,description,archetype,de,en,ode,oen,cases,axes):m.add(title,description,archetype,(de,en,ode,oen),cases,axes)
add('Apply specialisation, cooperation and coordination','The learner can explain specialisation, cooperation and coordination as principles of divided work and apply them to improvements in their own everyday environment.','procedure',
 'Spezialisierung bündelt Aufgaben und Fähigkeiten, Kooperation verbindet Beiträge und Koordination regelt Reihenfolge und Schnittstellen. Arbeitsteilung verbessert einen Ablauf nur, wenn Übergaben, Abhängigkeiten und verbleibende Engpässe zusammenpassen.',
 'Specialisation groups tasks and skills, cooperation combines contributions and coordination manages sequences and interfaces. Dividing work improves a process only when handovers, dependencies and remaining bottlenecks fit.',
 'Die Person erklärt in neuen lebensnahen Abläufen alle drei Prinzipien und wendet sie auf eine konkrete machbare Verbesserung mit Übergaben und einer Grenze an.',
 'In new everyday processes, the learner explains all three principles and applies them to a feasible improvement with handovers and a limitation.',
 [('school-snack-workflow','Für einen fiktiven Schulstand schneiden zwei Personen Obst, packen Portionen und geben sie aus. Bisher macht jede alles; eine Person schneidet besonders sicher, Verpackung benötigt fertige Stücke. Verbessere den Ablauf durch Spezialisierung, Kooperation und Koordination.',
   'At a fictional school stall, two people cut fruit, pack portions and serve them. Both currently do everything; one cuts especially safely, while packing requires cut pieces. Improve the process through specialisation, cooperation and coordination.',
   'Die Person begründet eine geeignete Aufgabenverteilung, erklärt den gemeinsamen Beitrag und plant sichere Übergaben/Reihenfolge. Sie benennt einen möglichen Engpass oder Ausfall und behauptet nicht, eine neue Aufteilung steigere ohne Bedingungen immer die Leistung.',
   'The learner justifies task allocation, explains cooperation and plans safe handovers and sequencing. They identify a bottleneck or absence and do not claim unconditional productivity gains from any new division.',
   'Alle drei Prinzipien in einem eigenen Lebensumfeldablauf.','All three principles in an everyday process.'),
  ('shared-flat-move','Eine andere Wohngemeinschaft zieht um: Kartons müssen beschriftet, zerbrechliche Sachen gepackt und an einen festen Abholplatz gebracht werden. Unterschiedliche Fähigkeiten und ein enger Transportweg sind gegeben. Erkläre die drei Prinzipien und wende sie für eine begründete Verbesserung an.',
   'Another shared household is moving: boxes need labels, fragile items need packing and boxes must reach a fixed collection point. Different skills and a narrow transport route are given. Explain the three principles and apply them to a justified improvement.',
   'Die Person unterscheidet passende spezialisierte Aufgaben, gemeinsames Arbeiten und vereinbarte Kennzeichnung/Transportfolge; sie verhindert doppelte Arbeit oder blockierte Übergaben. Sie berücksichtigt den engen Weg als Koordinationsgrenze, statt nur mehr Helfende zu verlangen.',
   'The learner distinguishes suitable specialised tasks, joint contribution and agreed labels/transport order, preventing duplicate work or blocked handovers. They recognise the narrow route as a coordination constraint rather than merely requesting more helpers.',
   'Schnittstellen und Engpass außerhalb des Verkaufsfalls.','Interfaces and a bottleneck outside a sales case.')],
 [('task-dependency','Fertiges Zwischenprodukt, Kennzeichnung und Transportreihenfolge.','Intermediate outputs, labelling and transport order.'),('allocation','Unterschiedliche Fähigkeiten, Engpass und Ausfall einer Person.','Different skills, bottlenecks and absence.')])
add('Represent a basic company structure','The learner can represent the basic structure of companies through key functional areas and their interactions.','representation',
 'Aufbauorganisation ordnet Aufgaben und Verantwortung Bereichen zu; Beschaffung, Leistungserstellung, Absatz und Leitung/Verwaltung wirken zusammen. Ein Organigramm zeigt Verantwortungsbeziehungen, nicht automatisch die gesamte zeitliche Reihenfolge eines Auftrags.',
 'An organisational structure allocates tasks and responsibilities to functions; procurement, operations, sales and management/administration interact. An organisation chart represents responsibility, not automatically an order’s entire timeline.',
 'Die Person stellt neue einfache Unternehmensstrukturen mit zentralen Funktionen und nachvollziehbaren Beziehungen dar und erklärt eine konkrete Zusammenarbeit zwischen Bereichen.',
 'The learner represents new simple company structures with key functions and meaningful relations, explaining a specific interaction between functions.',
 [('furniture-maker-functions','Eine fiktive Möbelwerkstatt kauft Holz, stellt Möbel her, verkauft sie und führt Personal/Buchhaltung unter einer Leitung. Stelle die grundlegenden Funktionsbereiche in einer geeigneten Übersicht dar und erläutere den Informationsweg bei einer Kundenänderung.',
   'A fictional furniture workshop buys timber, makes furniture, sells it and handles staff/accounting under one management. Represent its functions in a suitable overview and explain information flow when a customer changes an order.',
   'Die Person ordnet Beschaffung, Produktion, Absatz, Leitung/Verwaltung zu und stellt Verantwortungsbeziehungen konsistent dar. Sie erklärt Abstimmung Absatz→Produktion→Beschaffung und verwechselt sie nicht mit zwingend gleicher Hierarchie oder unverbundenen Abteilungen.',
   'The learner identifies procurement, production, sales and management/administration with consistent responsibility relationships. They explain sales–production–procurement coordination without assuming the same hierarchy or isolated departments.',
   'Verantwortungsstruktur und funktionale Abstimmung.','Responsibilities and functional coordination.'),
  ('repair-service-structure','Ein anderer Reparaturdienst hat Kundenannahme, Ersatzteilbeschaffung, Werkstatt und Verwaltung; ein kleines Team übernimmt mehrere Rollen. Stelle den Grundaufbau dar und erkläre Zusammenarbeit bei einem fehlenden Ersatzteil.',
   'Another repair service has customer reception, parts procurement, workshop and administration; one small team covers several roles. Represent its structure and explain collaboration when a part is unavailable.',
   'Die Person stellt Rollen trotz gemeinsamer Personen als Funktionen dar, verknüpft Werkstatt, Einkauf und Kundenkommunikation und berücksichtigt Leitung/Verwaltung. Sie setzt Funktionsbereich nicht mit zwingend eigener Person oder eigenem Raum gleich.',
   'The learner represents functions despite shared staff, links workshop, purchasing and customer communication, and includes management/administration. They equate neither functions with separate people nor departments with separate rooms.',
   'Funktionsaufbau auch in einem kleinen Dienstleistungsbetrieb.','Functional structure in a small service business.')],
 [('business-form','Sachgutherstellung versus Dienstleistung mit mehreren Rollen je Person.','Goods production versus services with several roles per person.'),('relationship','Verantwortung im Aufbau versus Zusammenarbeit im Auftragsablauf.','Structural responsibilities versus collaboration along an order.')])
add('Analyse core and support business processes','The learner can analyse companies through their core value-creation processes and supporting business processes.','concept',
 'Kernprozesse erzeugen die angebotene Leistung für Kundinnen und Kunden; unterstützende Prozesse ermöglichen sie. Entscheidend ist das konkrete Geschäftsmodell, nicht die Bezeichnung einer Tätigkeit: Dieselbe Tätigkeit kann in einem anderen Unternehmen zur Kernleistung gehören.',
 'Core processes create the service or product offered to customers; support processes enable it. Classification depends on the business model rather than an activity’s name: an activity may be core in one firm and support in another.',
 'Die Person rekonstruiert in neuen Unternehmen die zentrale Leistungskette, ordnet Unterstützungsprozesse begründet zu und erklärt eine notwendige Abhängigkeit.',
 'In new companies, the learner reconstructs the value-creation chain, justifies support-process classifications and explains a necessary dependency.',
 [('bakery-customer-value','Eine fiktive Bäckerei nimmt Bestellungen an, beschafft Zutaten, backt und verkauft Brot; Lohnabrechnung und Wartung sichern den Betrieb. Analysiere Kern- und Unterstützungsprozesse und die Folgen einer ausgefallenen Ofenwartung.',
   'A fictional bakery takes orders, obtains ingredients, bakes and sells bread; payroll and maintenance support operations. Analyse core and support processes and the consequences of failed oven maintenance.',
   'Die Person verbindet kundenbezogene Leistungserstellung und Absatz zur Kernkette, ordnet Lohnabrechnung/Wartung als Unterstützung ein und erklärt deren reale Bedeutung für die Kernleistung. Sie setzt unterstützend nicht mit entbehrlich gleich.',
   'The learner connects customer-facing production and delivery as the core chain, classifies payroll/maintenance as support and explains their importance. They do not equate supporting with dispensable.',
   'Kernwertschöpfung und notwendige Unterstützung.','Core value creation and necessary support.'),
  ('software-provider-and-restaurant','Vergleiche einen Softwareanbieter, dessen verkaufte Leistung Programmentwicklung und Wartung ist, mit einem Restaurant, das seine interne Bestellsoftware betreut. Analysiere die Rolle derselben IT-Tätigkeit in beiden Geschäftsmodellen.',
   'Compare a software provider selling program development/maintenance with a restaurant maintaining its internal ordering software. Analyse the same IT activity in the two business models.',
   'Die Person erklärt beim Softwareanbieter kundenbezogene IT als Kernprozess, im Restaurant die interne IT als Unterstützung der Bewirtung. Sie begründet über angebotene Leistung und Abhängigkeiten statt über eine feste Liste vermeintlich immer unterstützender Tätigkeiten.',
   'The learner identifies customer IT as core for the provider and internal IT as support for restaurant service. They justify classifications through the offer and dependencies rather than a fixed list of always-supporting activities.',
   'Geschäftsmodellabhängige Zuordnung derselben Tätigkeit.','Business-model-dependent classification of an activity.')],
 [('value-offer','Physische Ware, Bewirtung oder verkaufte IT-Leistung.','Physical goods, hospitality or an IT service.'),('support-link','Wartung, Personalabrechnung und interne Informationstechnik.','Maintenance, payroll and internal IT.')])
add('Analyse business workflows and production','The learner can analyse workflows, divided work, production design and information-technology support in specific companies.','procedure',
 'Ein Betriebsablauf verbindet Arbeitsschritte, Übergaben und Ressourcen. Einzel-/Varianten-/Massenfertigung sowie Werkstatt-/Fließfertigung passen unterschiedlich zu Menge und Varianten; IT kann Informationen koordinieren, beseitigt aber nicht automatisch physische Engpässe oder Fehler.',
 'Workflows connect tasks, handovers and resources. Custom, variant or mass production and workshop or flow arrangements suit volumes and variety differently; IT coordinates information but does not automatically remove physical bottlenecks or errors.',
 'Die Person analysiert in neuen Betriebsbeispielen Schritte und Arbeitsteilung, ordnet die Produktionsgestaltung passend ein und erläutert Nutzen sowie Grenze der gegebenen IT-Unterstützung.',
 'In new business cases, the learner analyses steps and divided work, classifies production design and explains benefits and limits of supplied IT support.',
 [('custom-furniture-workshop','Ein fiktiver Betrieb fertigt unterschiedliche Kundenmöbel in Sägen-, Schleif- und Lackierwerkstätten. Ein digitales Auftragsboard zeigt Freigaben; die Lackierstation ist überlastet. Analysiere Ablauf, Arbeitsteilung, Produktionsgestaltung und IT.',
   'A fictional firm makes different custom furniture in sawing, sanding and finishing workshops. A digital order board shows approvals, while finishing is overloaded. Analyse workflow, divided work, production and IT.',
   'Die Person rekonstruiert Übergaben und Werkstattorganisation für individuelle Aufträge, erklärt Transparenz/Freigaben durch das Board und den verbleibenden Lackierengpass. Sie nennt Koordination oder Kapazität als Ansatz, statt Digitalisierung allein mit höherem Durchsatz gleichzusetzen.',
   'The learner reconstructs handovers and workshop organisation for custom orders, explains the board’s transparency/approvals and the remaining finishing bottleneck, suggesting coordination or capacity rather than equating digitisation with throughput.',
   'Individuelle Produktion und nicht beseitigter physischer Engpass.','Custom production and a remaining physical bottleneck.'),
  ('bottle-line-with-variants','Ein anderer Betrieb füllt große Mengen Getränke auf einer Linie, wechselt aber zwischen drei Sorten. IT steuert Chargen und Etiketten; ein falscher Stammdateneintrag ordnet Etiketten falsch zu. Analysiere dieselben vier Aspekte.',
   'Another firm bottles large volumes on a line but switches among three drinks. IT controls batches and labels; incorrect master data map labels wrongly. Analyse the same four aspects.',
   'Die Person erklärt Fließablauf mit Varianten und Umrüst-/Abstimmungsbedarf, verbindet spezialisierte Aufgaben und digitale Chargenverfolgung und erläutert die Fehlerquelle. Sie erkennt effiziente Wiederholung und deren Grenze bei Änderungen, ohne Fehlerfreiheit von IT zu behaupten.',
   'The learner explains a flow line with variants and changeover needs, connects specialised tasks and batch tracking, and explains the data error. They identify efficient repetition and its limits under changes without claiming error-free IT.',
   'Linie, Varianten und Datenqualität.','A line, variants and data quality.')],
 [('production','Individuelle Werkstattaufträge versus Varianten auf einer Linie.','Custom workshop jobs versus variants on a line.'),('IT-limit','Freigabetransparenz, Engpass und falsche Stammdaten.','Approval transparency, bottlenecks and incorrect master data.')])
add('Analyse company presentations for their audiences','The learner can analyse company presentations through audience effects and criteria for effective presentation.','representation',
 'Eine Präsentation muss Zielgruppe, Botschaft, Belege, Aufbau, Sprache und Visualisierung aufeinander abstimmen. Verständlichkeit und behauptete Wirkung sind nicht dasselbe; Wirkung auf Adressaten braucht nachvollziehbare Hinweise statt bloß dekorativer Folien.',
 'A presentation aligns audience, message, evidence, structure, language and visuals. Clarity differs from claimed persuasion; audience effects require support rather than decoration alone.',
 'Die Person analysiert neue ganze Präsentationsmaterialien nach Adressaten, wesentlichen Aussagen, Belegen und Darstellungsentscheidungen und begründet eine gezielte Verbesserung sowie eine Wirkungsgrenze.',
 'The learner analyses new presentation materials through audience, key claims, evidence and design, justifying a targeted improvement and a limit to claimed effects.',
 [('student-apprenticeship-presentation','Eine fiktive Betriebspräsentation für Ausbildungssuchende verwendet zehn Folien voller Fachabkürzungen, nur Umsatzdaten und keine Tätigkeitsbeispiele. Material nennt Zielgruppe und eine kurze Rückmeldung der Zuhörenden. Analysiere die Adressatenwirkung nach klaren Kriterien.',
   'A fictional presentation for apprenticeship applicants uses ten abbreviation-heavy slides, only sales figures and no examples of work. Materials identify the audience and brief feedback. Analyse audience effects using explicit criteria.',
   'Die Person verknüpft Informationsbedarf mit fehlenden Tätigkeits-/Lernbeispielen, prüft Sprache/Reduktion und Belege und schlägt eine gezielte verständliche Darstellung vor. Sie unterscheidet gegebene Rückmeldung von unbelegter Behauptung, alle würden sich bewerben.',
   'The learner links information needs to missing work/training examples, assesses language, focus and evidence, and proposes a clear targeted display. They distinguish supplied feedback from claims that everyone would apply.',
   'Zielgruppe und Informationsbedarf statt bloßer Folienästhetik.','Audience needs rather than slide aesthetics alone.'),
  ('supplier-presentation-with-chart','Ein anderer Betrieb präsentiert einem Einkäufer Liefertreue mit einem Diagramm ohne Zeitraum/Bezugsgröße und wirbt allgemein mit bester Qualität. Einkäufer benötigt verlässliche Lieferbedingungen. Analysiere Sprache, Visualisierung, Belege und mögliche Wirkung.',
   'Another firm presents delivery reliability to a buyer using a chart without period or denominator and a generic best-quality claim. The buyer needs reliable supply terms. Analyse language, visuals, evidence and possible effects.',
   'Die Person fordert passende Perioden/Definitionen, konkrete Lieferbedingungen und sachliche Belege, erklärt deren Relevanz für diese Adressaten und eine mögliche Unsicherheit. Sie hält anschauliche Darstellung nicht automatisch für Wahrheit oder erfolgreichen Vertragsabschluss.',
   'The learner requests relevant periods/definitions, terms and evidence, explains their audience relevance and uncertainty, and equates clear visuals with neither truth nor a successful contract.',
   'Belegbarkeit und Zielgruppenrelevanz einer anderen Präsentation.','Evidence and relevance for a different audience.')],
 [('audience','Ausbildungssuchende versus Geschäftskunden.','Apprenticeship applicants versus business customers.'),('material','Fachwörter, fehlende Beispiele oder Grafik ohne Bezugsgröße.','Jargon, missing examples or a chart without a denominator.')])
add('Assess the importance of marketing for companies','The learner can assess the importance of marketing for company success using familiar products.','concept',
 'Marketing verbindet Angebot und Kundenbedarf über Produkt, Preis, Zugang und Kommunikation. Erfolg hängt auch von Kosten, Qualität und Umsetzung ab; Aufmerksamkeit oder Absatz allein beweisen weder Gewinn noch die alleinige Wirkung einer Werbemaßnahme.',
 'Marketing links offers and customer needs through product, price, access and communication. Success also depends on costs, quality and delivery; attention or sales alone proves neither profit nor an advertising effect.',
 'Die Person schätzt in neuen vertrauten Produktfällen die Bedeutung passender Marketingentscheidungen für Nachfrage und Unternehmenserfolg ein und benennt einen weiteren relevanten Erfolgsfaktor.',
 'In new familiar-product cases, the learner assesses how fitting marketing decisions affect demand and success, identifying another relevant factor.',
 [('reusable-bottle-target','Eine fiktive wiederverwendbare Flasche wird billig produziert, findet aber kaum Käufer: sie ist nur weit außerhalb des Schulwegs erhältlich, Nutzen und Reinigung sind unklar. Schätze die Bedeutung des Marketings für den Erfolg ein.',
   'A fictional reusable bottle is cheaply produced but sells poorly: it is available far from school routes and its benefits/cleaning are unclear. Assess marketing’s importance for success.',
   'Die Person verbindet erreichbaren Vertrieb, passende Produktinformation und Kundenbedarf mit Kaufbarrieren und berücksichtigt Qualität/Preis/Kosten als weitere Bedingungen. Sie erklärt mögliche Nachfragewirkung statt garantierten Erfolgs allein durch Werbung.',
   'The learner connects access, product information and needs to purchase barriers, considers quality/price/costs and explains potential demand effects rather than guaranteed success from advertising.',
   'Marktorientierung als mehr als Werbung.','Market orientation beyond advertising.'),
  ('snack-campaign-and-profit','Eine andere fiktive Snackaktion verdoppelt Verkäufe100→200, senkt aber Preis3→2 bei Stückkosten1,50 und zusätzlichen Kampagnenkosten80. Schätze die Bedeutung der Maßnahme für Erfolg anhand dieses begrenzten Modells ein.',
   'Another fictional snack promotion doubles sales100→200 while reducing price3→2, with unit cost1.50 and extra campaign cost80. Assess its importance for success in this bounded model.',
   'Die Person erklärt mögliche Aktivierung der Nachfrage, berechnet Vergleichsbeiträge150 vorher und100−80=20 nachher ohne weitere Fixkosten und trennt Absatz von Erfolg. Sie benennt eine mögliche längerfristige Wirkung nur als zu prüfende Bedingung.',
   'The learner explains possible demand activation, calculates contributions150 before versus100−80=20 after excluding other fixed costs, and separates sales from success. They treat longer-term effects as conditions requiring evidence.',
   'Nachfragebeitrag und Kosten einer Marketingaktion.','Demand and costs of marketing.')],
 [('market-fit','Erreichbarkeit, Produktinformation oder Preisaktion.','Access, information or a price promotion.'),('success-measure','Absatz, Deckungsbeitrag und längerfristige Kundenbindung.','Sales, contribution and longer-term retention.')])
add('Analyse marketing measures through their objectives','The learner can analyse measures from different marketing areas through objectives, design and mechanisms.','concept',
 'Produkt-, Preis-, Distributions- und Kommunikationsmaßnahmen setzen an unterschiedlichen Marktentscheidungen an. Ihre Ziele und Wirkungen hängen von Ausgestaltung und Zielgruppe ab; mehrere Bereiche können in einer Maßnahme zusammenwirken.',
 'Product, price, distribution and communication measures address different market decisions. Objectives and effects depend on design and audience; one measure can combine several areas.',
 'Die Person analysiert in neuen Produktfällen Maßnahmen aus mehreren Marketingbereichen nach Ziel, konkreter Ausgestaltung und Wirkungsweg und erkennt eine bedingte Nebenwirkung.',
 'In new product cases, the learner analyses measures across marketing areas through objectives, specific design and mechanisms, identifying a conditional side effect.',
 [('bicycle-product-price-channel','Eine fiktive Fahrradmarke bietet austauschbare Teile, einen Reparaturservice beim örtlichen Händler, einen Einführungsrabatt und eine Anleitungskampagne. Analysiere Maßnahmen nach Marketingbereich, Ziel und Wirkung.',
   'A fictional bicycle brand offers replaceable parts, local dealer repairs, an introductory discount and an instruction campaign. Analyse each measure’s marketing area, objective and mechanism.',
   'Die Person ordnet Produkt-/Servicegestaltung, Vertrieb, Preis und Kommunikation nachvollziehbar zu, erklärt unterschiedliche Kauf-/Nutzungsbarrieren und Wechselwirkungen. Sie berücksichtigt etwa Rabatterwartungen oder Servicekapazität statt jeden Effekt sicher positiv zu behaupten.',
   'The learner classifies product/service design, distribution, pricing and communication, explaining distinct purchase/use barriers and interactions, including discount expectations or service capacity rather than guaranteed positive effects.',
   'Mehrere Marketingbereiche im konkreten Wirkungszusammenhang.','Several marketing areas and their mechanisms.'),
  ('meal-box-target-shift','Ein anderer Anbieter richtet eine Mahlzeitenbox nun an kleine Haushalte: kleinere Portionen, Abholung statt Lieferung, Mengenpreis und kurze Rezeptvideos. Analysiere Ziele, Ausgestaltung und Wirkungswege und eine mögliche Spannung.',
   'Another provider targets meal boxes at small households: smaller portions, collection rather than delivery, volume pricing and short recipe videos. Analyse objectives, designs, mechanisms and one tension.',
   'Die Person erklärt Zielgruppenpassung der Portion und Kommunikation, Zugangsfolgen der Abholung und Preisanreiz zur Menge. Sie erkennt möglichen Widerspruch zwischen kleinen Haushalten und Mengenanreiz und trennt Maßnahmen von nachzuweisendem Kaufverhalten.',
   'The learner explains portions and communication, access effects of collection and volume incentives, identifies tension between small households and volume discounts, and separates measures from evidenced buying behaviour.',
   'Zielpassung und Konflikt zwischen Maßnahmen.','Audience fit and conflict between measures.')],
 [('marketing-area','Produkt, Preis, Vertrieb und Kommunikation im selben Fall.','Product, price, distribution and communication in one case.'),('target','Nutzungsdauer, kleine Haushalte oder bequemer Zugang.','Durability, small households or convenient access.')])
add('Develop a simple criteria-based marketing concept','The learner can combine coordinated marketing measures for selected products into a simple concept and justify choices using criteria.','modeling',
 'Ein einfaches Marketingkonzept verbindet Zielgruppe, Ziel und abgestimmte Produkt-, Preis-, Vertriebs- und Kommunikationsentscheidungen. Die Auswahl muss zu Budget, Nutzung und Produktphase passen; eine Sammlung einzelner Ideen ist ohne Konsistenz kein Konzept.',
 'A simple marketing concept combines audience, objective and coordinated product, pricing, distribution and communication choices. It must fit budget, use and product stage; unrelated ideas are not a coherent concept.',
 'Die Person entwickelt in neuen begrenzten Produktfällen ein abgestimmtes Konzept über mehrere Marketingbereiche, begründet es mit vorgegebenen Kriterien und passt es bei einer neuen Bedingung konsistent an.',
 'In new bounded product cases, the learner develops a coordinated concept across marketing areas, justifies it through criteria and adapts it consistently to a new condition.',
 [('school-stationery-launch','Für einen fiktiven Schulverkauf sollen nachfüllbare Stifte eingeführt werden. Zielgruppe hat kleines Budget, möchte verlässliches Material; Absatz nur an zwei Schulpausen und Kommunikationsbudget40 Euro. Entwickle ein einfaches abgestimmtes Marketingkonzept und begründe Auswahl.',
   'A fictional school stall introduces refillable pens. Customers have limited funds and want reliability; selling is restricted to two school breaks and communication budget is EUR40. Develop and justify a coordinated simple concept.',
   'Die Person stimmt Produktnutzen, nachvollziehbaren Preis, passenden Pausenvertrieb und bezahlbare sachliche Kommunikation ab und verbindet jede Entscheidung mit Zielgruppe/Budget. Sie hält einen Werbekanal ohne passende Liefer- und Preisentscheidung nicht für ein vollständiges Konzept.',
   'The learner aligns product benefits, a defensible price, break-time distribution and affordable factual communication, linking choices to audience/budget. One advertising channel without supply/pricing choices is not a complete concept.',
   'Eigene kohärente Gestaltung unter knappen Ressourcen.','Coherent design under scarce resources.'),
  ('mature-repair-kit-new-audience','Ein anderes fiktives etabliertes Reparaturset soll jetzt ältere Nutzer erreichen; Material nennt verständliche Anleitung, lokale Beratungsstellen, Preisobergrenze und geringe digitale Reichweite. Entwickle Maßnahmen, begründe sie und passe bei Wegfall einer Beratungsstelle einen Zusammenhang an.',
   'Another established fictional repair kit targets older users; materials give needs for clear instructions, local advice, a price ceiling and limited digital reach. Develop and justify measures, then adapt them if an advice venue closes.',
   'Die Person verbindet verständliches Produkt/Anleitung, leistbaren Preis, zugänglichen Vertrieb und passende Kommunikation; sie reagiert auf den geänderten Zugang mit einer verfügbaren Alternative und angepasster Information. Sie übernimmt kein unverändertes digitales Jugendkonzept.',
   'The learner combines clear product/instructions, affordable pricing, accessible distribution and suitable communication, adapting access and information when the venue closes rather than copying a youth-focused online concept.',
   'Neue Zielgruppe und konsistente Konzeptanpassung.','A different audience and consistent adaptation.')],
 [('audience-stage','Neue Schulware versus etabliertes Produkt für ältere Nutzer.','A new school product versus an established product for older users.'),('constraint','Budget, Preisobergrenze, Vertriebsfenster und weggefallener Zugang.','Budget, price ceiling, selling windows and lost access.')])
add('Prepare a simplified balance sheet','The learner can prepare a simplified balance sheet by setting assets against sources of capital.','representation',
 'Eine Bilanz stellt Vermögen am Stichtag seiner Finanzierung gegenüber: Aktiva als Mittelverwendung, Eigen- und Fremdkapital als Mittelherkunft. Eigenkapital ist Residualgröße, nicht automatisch Bargeld; Zeitpunkt und gleiche Bewertungsbasis sind entscheidend.',
 'A balance sheet compares assets at a date with their financing: assets as uses of funds and equity/liabilities as sources. Equity is a residual, not automatically cash; timing and consistent valuation matter.',
 'Die Person erstellt in neuen vereinfachten Fällen eine ausgeglichene Bilanz, ordnet Anlage-/Umlaufvermögen und Kapitalquellen sinnvoll zu und erklärt die Bilanzgleichung.',
 'In new simplified cases, the learner prepares a balanced balance sheet, classifies fixed/current assets and capital sources, and explains the accounting equation.',
 [('opening-workshop-balance','Eine fiktive Werkstatt hat am Stichtag Maschine6000, Vorräte2000 und Bankguthaben1000 Euro; Darlehen4000, sonst keine Schulden. Erstelle eine vereinfachte Bilanz und erkläre Eigenkapital.',
   'At a reference date, a fictional workshop has a machine worth EUR6000, inventories2000 and bank funds1000, with a4000 loan and no other liabilities. Prepare a simplified balance sheet and explain equity.',
   'Die Person ordnet Maschine dem Anlagevermögen und Vorräte/Bank dem Umlaufvermögen zu, ermittelt Vermögen9000, Fremdkapital4000 und Eigenkapital5000. Sie zeigt gleiche Summen und erklärt, dass Eigenkapital5000 nicht verfügbares Bankguthaben1000 ist.',
   'The learner classifies the machine as fixed and inventory/bank as current assets, calculates assets9000, debt4000 and equity5000, shows equal totals and distinguishes equity5000 from bank funds1000.',
   'Gegenüberstellung und Residualgröße statt Bargeldverwechslung.','Opposing uses/sources and a residual rather than cash.'),
  ('service-business-receivables','Ein anderer fiktiver Dienstleister besitzt Computer3000, Forderungen1500 und Kasse500; Lieferantenverbindlichkeiten1000 und Bankkredit2000. Stelle zum gegebenen Stichtag Bilanz und Mittelherkunft dar; die Forderung ist noch nicht bezahlt.',
   'Another fictional service firm has computers3000, receivables1500 and cash500, with supplier payables1000 and bank borrowing2000. Prepare its dated balance sheet and sources of funds; receivables remain unpaid.',
   'Die Person ermittelt Vermögen5000, Fremdkapital3000 und Eigenkapital2000 und ordnet Forderung als Vermögen ohne gegenwärtige Kassenverfügbarkeit ein. Sie zählt Finanzierung nicht nochmals als zusätzliches Aktivvermögen und hält Stichtagsbestand von Periodenerfolg getrennt.',
   'The learner calculates assets5000, debt3000 and equity2000, recognises receivables as assets without current cash, avoids counting financing again as assets and separates dated stocks from period profit.',
   'Forderungen und Finanzierung in einem Dienstleistungsfall.','Receivables and financing in a service firm.')],
 [('asset','Maschine/Vorrat versus Computer/Forderung.','Machines/inventory versus computers/receivables.'),('funding','Darlehen, Lieferantenverbindlichkeit und residualer Eigenanteil.','Loans, supplier payables and residual equity.')])
add('Represent transactions in the balance sheet','The learner can represent the effects of simple transactions on the balance sheet and identify the basic principle of double-entry bookkeeping.','procedure',
 'Jeder einfache Geschäftsvorfall verändert zusammenhängende Bilanzposten; Vermögen bleibt gleich Eigenkapital plus Schulden. Aktiv-/Passivtausch und Bilanzverlängerung/-verkürzung unterscheiden sich; doppelte Buchführung bedeutet zusammengehörige gleich große Soll-/Habenbuchung, nicht zweimal denselben Vorgang zählen.',
 'A simple transaction changes related balance-sheet items while assets equal equity plus liabilities. Asset/liability swaps differ from expansions/contractions; double entry records equal linked debit/credit amounts, not the same event twice.',
 'Die Person stellt in neuen einfachen Fällen die betroffenen Bilanzposten mit Richtung und Betrag dar, prüft die Gleichung und erläutert die zusammenhängende doppelte Erfassung.',
 'In new simple cases, the learner shows affected items, directions and amounts, checks the equation and explains linked double entry.',
 [('equipment-cash-versus-credit','Eine fiktive Firma kauft eine Maschine2000 Euro. VarianteA bezahlt vom Bankkonto; VarianteB erhält ein neues Darlehen2000, das die Maschine finanziert. Keine Steuern/weitere Effekte im Modell. Stelle Bilanzänderungen und Prinzip der doppelten Buchung dar.',
   'A fictional firm buys a machine for EUR2000. VariantApays from bank funds;Buses a new2000 loan. The model excludes taxes and other effects. Represent balance changes and double entry.',
   'Die Person erklärt Maschine+2000/Bank−2000 als Aktivtausch und Maschine+2000/Darlehen+2000 als Verlängerung, ohne Kauf allein als Aufwand zu buchen. Sie erläutert gleich große zusammengehörige Kontenänderungen und ausgeglichene Bilanz.',
   'The learner explains machine+2000/bank−2000 as an asset swap and machine+2000/loan+2000 as expansion, without treating acquisition alone as expense, and describes equal linked entries preserving balance.',
   'Gleicher Kauf mit verschiedener Finanzierungswirkung.','The same purchase under different financing.'),
  ('repayment-and-debt-conversion','Ein anderer fiktiver Fall tilgt Darlehen500 vom Bankkonto; anschließend wird eine Lieferantenschuld300 durch gleich hohen längerfristigen Kredit ersetzt. Zinsen/Steuern sind ausgeschlossen. Stelle beide Vorgänge dar und ordne ihre Bilanzart ein.',
   'Another fictional case repays loan500 from bank funds and then replaces supplier debt300 with an equal longer-term loan. Interest/taxes are excluded. Represent both transactions and classify the changes.',
   'Die Person erklärt Bank−500/Schuld−500 als Verkürzung und Lieferantenschuld−300/Kredit+300 als Passivtausch; Eigenkapital bleibt im Modell unverändert. Sie trennt Tilgung von Zinsaufwand und nennt die korrespondierenden Buchungsseiten.',
   'The learner explains bank−500/debt−500 as contraction and supplier debt−300/loan+300 as a liability swap, with equity unchanged, distinguishes repayment from interest expense and identifies corresponding posting sides.',
   'Verkürzung und Passivtausch ohne falschen Erfolg.','Contraction and liability swaps without false profit effects.')],
 [('transaction','Anschaffung, Tilgung und Ersatz einer Schuld.','Acquisition, repayment and replacing a liability.'),('classification','Aktiv-/Passivtausch versus Bilanzverlängerung/-verkürzung.','Asset/liability swaps versus expansion/contraction.')])
add('Explain transactions affecting profit','The learner can explain the effects of simple transactions affecting profit and classify income and expense accounts as subaccounts of equity.','procedure',
 'Aufwand mindert, Ertrag erhöht den Periodenerfolg und über den Abschluss das Eigenkapital. Zahlung und Erfolg sind verschiedene Abgrenzungen: Einzahlung auf eine bestehende Forderung ist kein neuer Ertrag, Tilgung kein Zinsaufwand; Erfolgskonten sammeln erfolgswirksame Vorgänge als Unterkonten des Eigenkapitals.',
 'Expenses reduce and income increases period profit and, through closing, equity. Payment and profit differ: collecting an existing receivable is not new income and principal repayment is not interest expense. Income and expense accounts collect profit-affecting transactions as subaccounts of equity.',
 'Die Person erklärt in neuen Fällen Aufwand/Ertrag, Erfolgsrichtung und Bezug zum Eigenkapital, unterscheidet erfolgsneutrale Zahlungsvorgänge und ordnet Erfolgskonten sachgerecht ein.',
 'In new cases, the learner explains income/expense, profit direction and equity effects, separates payments without new profit effects and correctly classifies income and expense accounts.',
 [('rent-revenue-and-old-receivable','Eine fiktive Dienstleistungsfirma leistet im Monat einen Auftrag für150 Euro auf Rechnung, zahlt80 Euro Monatsmiete und erhält100 Euro auf eine bereits früher erfasste Forderung. Sonstige Effekte sind ausgeschlossen. Erkläre die jeweiligen Erfolgs- und Eigenkapitalwirkungen sowie die Funktion der Erfolgskonten.',
   'A fictional service firm completes work worth EUR150 on account, pays EUR80 rent for the month and receives EUR100 against a receivable recorded earlier. Other effects are excluded. Explain each profit/equity effect and the role of income and expense accounts.',
   'Die Person ordnet den Auftrag als Ertrag+150 und die Miete als Aufwand80 ein; der betrachtete Erfolg erhöht Eigenkapital um70. Der Forderungseingang tauscht Bank gegen Forderung und erzeugt keinen zweiten Ertrag. Sie erklärt das Sammeln und Abschließen der Erfolgskonten zum Eigenkapital.',
   'The learner classifies the work as income150 and rent as expense80, yielding profit70 and an equity increase70. Collecting the old receivable swaps bank funds for receivables without new income. They explain collecting transactions in income/expense accounts and closing them to equity.',
   'Periodenleistung statt bloßer Zahlungsbetrachtung.','Period performance rather than cash alone.'),
  ('acquisition-depreciation-interest','Eine andere fiktive Firma kauft ein Gerät für1000 Euro aus Bankmitteln. Für die betrachtete Periode ist eine Abschreibung200 Euro vorgegeben. Sie zahlt außerdem100 Euro Darlehenstilgung und20 Euro Zinsen dieser Periode. Ordne die Vorgänge und erkläre Erfolgskonten; keine Steuern oder weiteren Effekte.',
   'Another fictional firm buys equipment for EUR1000 from bank funds. Depreciation of EUR200 is given for this period. It also pays EUR100 loan principal and EUR20 interest for the period. Classify the transactions and explain income/expense accounts; exclude taxes and other effects.',
   'Die Person trennt erfolgsneutralen Gerätekauf und Tilgung von Abschreibungsaufwand200 und Zinsaufwand20; Erfolg und Eigenkapital sinken um220. Sie erläutert erfolgswirksame Aufwandskonten als Unterkonten des Eigenkapitals, statt alle Auszahlungen als Aufwand zu behandeln.',
   'The learner separates equipment acquisition and principal repayment without immediate profit effects from depreciation expense200 and interest expense20, reducing profit/equity by220. They explain expense accounts as subaccounts of equity rather than treating every payment as expense.',
   'Nicht zahlungswirksamer Aufwand und erfolgsneutrale Auszahlung.','Non-cash expense and a payment without profit effects.')],
 [('recognition','Leistung/Forderungseinzug versus Kauf/Abschreibung/Tilgung/Zins.','Performance/collection versus acquisition/depreciation/principal/interest.'),('equity','Positive und negative Periodenergebnisse.','Positive and negative period outcomes.')])
add('Calculate business profit using an income statement','The learner can calculate a business\'s profit or loss by comparing expenses and income in an income statement.','procedure',
 'Die Gewinn- und Verlustrechnung stellt periodengerecht Erträge und Aufwendungen gegenüber; ihre Differenz ist Gewinn oder Verlust. Umsatz ist nicht Gewinn, Liquidität ist nicht Erfolg, und bereits erfasste Zahlungsforderungen werden nicht als zusätzlicher Ertrag gezählt.',
 'An income statement compares income and expenses for a period; their difference is profit or loss. Revenue is not profit, cash availability is not profit, and collecting amounts already recognised does not create additional income.',
 'Die Person ordnet neue Periodendaten vollständig und ohne Doppelzählung in eine GuV, berechnet Gewinn oder Verlust und erläutert Abweichungen von Umsatz und Zahlungsüberschuss.',
 'The learner organises new period data into an income statement without omissions or double counting, calculates profit/loss and explains differences from revenue and cash surplus.',
 [('cafe-earned-unpaid-revenue','Ein fiktives Café erzielt im Monat8000 Euro Umsatzerlöse, davon sind1000 noch nicht bezahlt. Aufwand der Periode: eingesetzte Waren3000, Löhne2500, Miete1000 und vorgegebene Abschreibung500. Erstelle die vereinfachte GuV; alle Leistungen und Aufwendungen gehören in diesen Monat.',
   'A fictional cafe earns EUR8000 revenue in a month, including EUR1000 not yet paid. Period expenses are consumed goods3000, wages2500, rent1000 and given depreciation500. Prepare its simplified income statement; all performance/expenses belong to this month.',
   'Die Person stellt Ertrag8000 Aufwand7000 gegenüber und ermittelt Gewinn1000; sie zählt ausstehende Zahlung als bereits verdienten Ertrag und Abschreibung als Aufwand ohne aktuelle Auszahlung. Sie verwechselt weder Umsatz8000 noch Zahlungssaldo mit Gewinn1000.',
   'The learner compares income8000 with expenses7000, yielding profit1000, includes earned unpaid revenue and non-cash depreciation and distinguishes profit from revenue8000 and cash balances.',
   'Gewinn trotz ausstehender Zahlung mit nicht zahlungswirksamem Aufwand.','Profit with unpaid earned revenue and non-cash expense.'),
  ('repair-service-loss','Ein anderer fiktiver Reparaturbetrieb hat periodengerechte Erträge4500 und Materialaufwand1800, Personal2200, Miete800, Zinsen100. Zusätzlich werden500 auf eine Forderung aus dem Vormonat eingezahlt. Erstelle die GuV und erkläre das Ergebnis.',
   'Another fictional repair firm has period income4500 and expenses for materials1800, staff2200, rent800 and interest100. An additional500 is collected on a receivable from the previous month. Prepare the income statement and explain its result.',
   'Die Person summiert Aufwendungen4900, berechnet Verlust400 und ordnet den Alt-Forderungseingang nicht nochmals als Periodenertrag ein. Sie erklärt, dass vorhandene Einzahlungen einen Verlust nicht ausschließen und der Verlust das Eigenkapital mindert.',
   'The learner sums expenses4900, calculates loss400 and excludes collection of old receivables from new period income. They explain that cash receipts do not rule out a loss and that the loss reduces equity.',
   'Eigenständiger Verlustfall mit Altzahlung und Periodenabgrenzung.','An independent loss case with an old receipt and period recognition.')],
 [('outcome','Gewinn und Verlust bei unterschiedlichen Geschäftstätigkeiten.','Profit and loss in different activities.'),('timing','Verdient aber unbezahlt versus Zahlung auf Altleistung.','Earned but unpaid versus collection for earlier performance.')])
add('Analyse balance sheets and income statements using ratios','The learner can analyse simplified balance sheets and income statements, calculate selected financial ratios and interpret them in relation to the industry.','data',
 'Kennzahlen setzen Größen aus Bilanz und GuV in definierte Beziehungen. Bezugszeitraum und Nenner bestimmen die Aussage. Eigenkapitalquote, Eigenkapitalrentabilität und Umsatzrentabilität erklären verschiedene Aspekte; Branche, Kapitalbindung und Geschäftsmodell begrenzen allgemeine Ranglisten.',
 'Financial ratios relate specified balance-sheet and income-statement quantities. Period and denominator determine the meaning. Equity ratio, return on equity and profit margin concern different aspects; industry, capital intensity and business model limit universal rankings.',
 'Die Person berechnet definierte Kennzahlen aus neuen vereinfachten Abschlüssen, erläutert die Bezugsgrößen und interpretiert Unterschiede unter branchenspezifischen Bedingungen ohne universellen Idealwert oder Kausalitätsbehauptung.',
 'The learner calculates defined ratios from new simplified accounts, explains denominators and interprets differences under industry-specific conditions without universal ideal values or unsupported causal claims.',
 [('capital-intensive-versus-service','Fiktive Jahresdaten: Dienstleister Vermögen100, Stichtags-Eigenkapital40, durchschnittliches Eigenkapital40, Umsatz200, Gewinn20; Produzent600/180/180/300/30 in derselben Reihenfolge. Berechne Eigenkapitalquote(EK/Vermögen), Eigenkapitalrentabilität(Gewinn/durchschnittliches EK) und Umsatzrentabilität(Gewinn/Umsatz). Interpretiere unter der Annahme höherer Kapitalbindung der Produktion.',
   'Fictional annual data: service firm assets100, closing equity40, average equity40, revenue200, profit20; manufacturer600/180/180/300/30 in that order. Calculate equity/assets, profit/average equity and profit/revenue. Interpret assuming manufacturing has higher capital intensity.',
   'Die Person berechnet für den Dienstleister40%,50%,10% und Produzenten30%,rund16,7%,10%. Sie erklärt gleiche Umsatzmarge bei verschiedenen Eigenkapital- und Vermögensbasen und berücksichtigt Kapitalbindung; sie folgert keine allgemeine Überlegenheit oder Krisensicherheit nur aus einer Zahl.',
   'The learner calculates40%,50%,10% for services and30%,approximately16.7%,10% for manufacturing, explains equal margins with different equity/asset bases and considers capital intensity rather than inferring universal superiority or crisis safety.',
   'Gleiche Marge bei verschiedenen Kapitalbezügen.','Equal margins with different capital bases.'),
  ('retail-versus-specialist-service','Neue fiktive Jahresdaten: Handel Vermögen400, Stichtags-/durchschnittliches Eigenkapital100, Umsatz1000, Gewinn20; Spezialdienstleistung100/50/200/20. Nutze dieselben definierten Kennzahlen. Das Fallmaterial beschreibt hohen Warenumschlag im Handel und personengebundene Leistungen beim Dienstleister. Begründe eine begrenzte Interpretation.',
   'New fictional annual data: retailer assets400, closing/average equity100, revenue1000, profit20; specialist service100/50/200/20. Use the same defined ratios. The case describes high stock turnover in retail and staff-based services. Justify a bounded interpretation.',
   'Die Person ermittelt Handel25% Eigenkapitalquote,20% Eigenkapitalrentabilität und2% Umsatzmarge; Dienstleistung50%,40%,10%. Sie erklärt trotz gleichen Gewinns unterschiedliche Nenner und diskutiert Branchen-/Umschlagbedingungen, statt niedrige Marge allein als mangelnden Unternehmenserfolg zu deuten.',
   'The learner obtains25% equity ratio,20% return on equity and2% margin for retail versus50%,40%,10% for services, explains different denominators despite equal profit and discusses industry/turnover conditions rather than equating low margin with failure.',
   'Niedrige Handelsmarge ist ohne Bezugsgrößen kein Erfolgsurteil.','A low retail margin alone does not establish business failure.')],
 [('industry','Kapitalintensive Produktion, Dienstleistung und Handel.','Capital-intensive manufacturing, services and retail.'),('denominator','Vermögen, durchschnittliches Eigenkapital und Umsatz getrennt.','Assets, average equity and revenue kept distinct.')])
add('Visualise balance-sheet and income-statement information','The learner can use spreadsheet software to visualise balance-sheet and income-statement information or its development in ways suited to the target audience.','representation',
 'Eine finanzielle Grafik übersetzt ausgewählte Bilanz-/GuV-Daten in eine zur Aussage und Zielgruppe passende Darstellung. Zeitraum, Einheit, Bestands-/Stromgrößen, Bezugsgrößen und Achsen müssen transparent bleiben; Tabellenkalkulation bindet Grafiken an überprüfbare Eingabedaten statt bloß dekorative Bilder.',
 'A financial chart translates selected accounts data into a representation suited to message and audience. Period, units, stocks/flows, denominators and axes remain explicit; spreadsheet charts link to checkable input data rather than serving as decoration.',
 'Die Person erstellt aus neuen Bilanz-/GuV-Daten eine tatsächlich datenverknüpfte Tabellenkalkulationsgrafik, begründet Form und Zielgruppenbezug, prüft einen Eingabewechsel und erläutert die fachlichen Aussagegrenzen.',
 'The learner creates an actual data-linked spreadsheet chart from new accounts data, justifies its type and audience fit, checks an input change and explains limits of interpretation.',
 [('annual-revenue-and-profit-trend','Fiktive Jahresdaten für eine Präsentation vor Auszubildenden: Umsatz2023/2024/2025=100/120/140, Gewinn=10/12/7 in TausendEuro. Erstelle Tabelle und passende Grafik in einer Tabellenkalkulation. Ändere Gewinn2025 auf14 und prüfe die Aktualisierung; erkläre Entwicklung und Grenzen.',
   'Fictional annual data for an apprentice presentation: revenue2023/2024/2025=100/120/140 and profit=10/12/7, in EURthousands. Create a spreadsheet table/chart, change2025profit to14 and check updating. Explain the development and limits.',
   'Die Person erstellt nachvollziehbar verknüpfte Reihen mit eindeutigen Jahren/Einheiten und für die kleinen Gewinnwerte erkennbarer Darstellung ohne versteckte Achsenverzerrung. Sie zeigt Aktualisierung7→14, erklärt zunächst steigenden Umsatz bei fallendem letztem Gewinn und trennt Umsatz/Erfolg; Ursachen sind aus den Reihen allein nicht belegt.',
   'The learner creates linked series with clear years/units and legible profit values without hidden axis distortion, demonstrates updating7to14, explains initially rising revenue with falling final profit and distinguishes revenue/profit without inventing causes.',
   'Zeitreihen verschiedener Größen und tatsächliche Datenbindung.','Time series with different magnitudes and actual data linkage.'),
  ('dated-capital-structure','Ein anderer fiktiver Betrieb weist am selben Stichtag Vermögen200 aus, finanziert durch Eigenkapital60 und Schulden140, jeweils TausendEuro. Für eine Gesprächsrunde mit Lieferanten stelle Kapitalstruktur mit Tabellenkalkulation dar. Prüfe ein neues gegebenes Szenario EK80/Schulden120 bei Vermögen200 und begründe die Form.',
   'Another fictional firm has dated assets200, financed by equity60 and debt140, all EURthousands. Visualise the funding structure in a spreadsheet for suppliers. Check a new given scenario equity80/debt120 with assets200 and justify the chart.',
   'Die Person bildet Finanzierungsteile60/140 beziehungsweise30%/70% klar als gleichen Gesamtwert200 ab und zeigt nach Datenänderung80/120 beziehungsweise40%/60%. Sie wählt etwa gestapelte Balken mit sichtbaren Bezugsgrößen, vermeidet zusätzliche Vermögenssäule als dritten Anteil und erklärt, dass Bestandsstruktur keinen Periodengewinn oder sichere Zahlungsfähigkeit beweist.',
   'The learner shows financing60/140 as30%/70% of200 and updates to80/120 or40%/60%, chooses e.g. a stacked bar with explicit totals, avoids adding assets as a third funding share and explains that dated structure proves neither period profit nor guaranteed solvency.',
   'Bestandsanteile statt Zeitreihe und doppelte Gesamtsumme.','Dated shares rather than a time series or double-counted total.')],
 [('data','Mehrjährige GuV-Reihen versus stichtagsbezogene Kapitalstruktur.','Multi-year income-statement series versus dated capital structure.'),('audience','Auszubildende versus Lieferanten mit begründetem Informationsbedarf.','Apprentices versus suppliers with justified information needs.')])
add('Present a business model and basic entrepreneurial decisions','The learner can systematically present their own business model within a project, including essential elements of a successful business, its core process and basic entrepreneurial decisions.','modeling',
 'Ein eigenes Geschäftsmodell verbindet Zielkundschaft, Nutzenversprechen, Leistungserstellung, Ressourcen/Partner, Erlös-/Kostenlogik und begründete Grundentscheidungen in einem zusammenhängenden Projekt. Ein Kernprozess macht die Leistungserstellung nachvollziehbar; ein Modell ist eine überprüfbare Annahme, kein Erfolgsgarant.',
 'An original business model connects customers, value proposition, delivery, resources/partners, revenue/cost logic and basic decisions in a coherent project. A core process makes delivery explicit; a model is a testable assumption rather than a guarantee of success.',
 'Die Person stellt ein eigenes Projektmodell systematisch dar, verknüpft wesentliche Elemente mit Kernprozess und Grundentscheidungen und prüft unter neuen Bedingungen Konsistenz und Annahmen, statt bloß eine Produktidee oder Werbeaktion aufzuzählen.',
 'The learner systematically presents an original project model, links its essential elements, core process and basic decisions and checks coherence/assumptions under new conditions rather than listing a product idea or promotion.',
 [('repair-popup-project','Entwickle für ein fiktives Schulprojekt ein eigenes Modell für einen Fahrrad-Reparaturtag unter vorgegebenen Bedingungen: vierTeammitglieder, Werkzeuge leihbar, nur zuvor geübte sichere Arbeiten undBudget100Euro. Stelle Kundschaft/Nutzen, Kernprozess vom Auftrag zur Übergabe, Ressourcen/Partner, Erlöse/Kosten und begründete Entscheidungen dar. Prüfe bei doppelt so vielen Anfragen die Durchführbarkeit.',
   'Develop your own fictional school-project model for a bicycle repair day: four team members, borrowed tools, only previously practised safe tasks and EUR100budget. Present customers/value, the order-to-handover process, resources/partners, revenues/costs and justified decisions. Check feasibility if enquiries double.',
   'Die Person entwirft zusammenhängende Elemente, begrenzt sichere Leistungen und Kapazität, macht Einnahmen/Kostenannahmen transparent und begründet Organisation/Partner/Leistungsumfang. Sie passt etwa Termine oder Umfang bei verdoppelter Nachfrage an, benennt zu prüfende Nachfrage-/Kostenannahmen und behauptet keinen garantierten Gewinn.',
   'The learner builds coherent elements, limits safe services/capacity, makes revenue/cost assumptions explicit and justifies organisation, partners and scope. They adapt scheduling or scope when demand doubles, identify assumptions needing tests and do not guarantee profit.',
   'Eigenes Dienstleistungsmodell mit Kapazitätsprüfung.','An original service model with a capacity check.'),
  ('reusable-event-kit-project','Entwickle ein zweites eigenes fiktives Projektmodell für die Ausleihe wiederverwendbarer Veranstaltungssets. Gegeben sind Lagerfläche für20Sets, Rücknahme/Reinigung als notwendige Schritte und eine Zielgruppe kleiner Vereine. Stelle die wesentlichen Elemente, den vollständigen Kernprozess und Grundentscheidungen dar; prüfe eine verzögerte Rückgabe jedes drittenSets.',
   'Develop a second original fictional project model for reusable event-kit rental: storage for20kits, required return/cleaning and small clubs as customers. Present essential elements, the full core process and basic decisions; check delayed return of every third kit.',
   'Die Person verbindet Nutzen, Verleih-/Rücknahme-/Reinigungsprozess, Lager/Kapazität, Partner und Kosten-/Erlösannahmen mit begründeten Entscheidungen wie Buchungspuffer und Rückgabevereinbarung. Sie berücksichtigt geringere verfügbare Kapazität bei Verzögerungen, prüft Anpassungen und hält Geschäftsmodell, Marketing und garantierten Erfolg auseinander.',
   'The learner links value, rental/return/cleaning, storage/capacity, partners and revenue/cost assumptions to decisions such as booking buffers and return arrangements, considers lower available capacity under delays and separates a business model from marketing and guaranteed success.',
   'Eigenes Verleihmodell mit Rücklauf und Kapazitätsrisiko.','An original rental model with return flows and capacity risk.')],
 [('model','Reparaturdienst versus wiederkehrender Verleih-/Rücklaufprozess.','Repair services versus recurring rental/return.'),('constraint','Verdoppelte Nachfrage versus verzögerte Rückgabe.','Doubled demand versus late returns.')])
add('Reflect on personal requirements in business roles','The learner can compare their own interests and strengths with requirements for entrepreneurs and employees and use the comparison for career orientation.','concept',
 'Berufliche Orientierung vergleicht freiwillig ausgewählte eigene Interessen/Stärken mit konkreten Tätigkeitsanforderungen an Unternehmensgründung und Beschäftigung. Fähigkeiten können entwickelt werden; Persönlichkeitslisten beweisen weder Eignung noch Nichteignung oder späteren Erfolg. Ein begründeter Erkundungsschritt hält Möglichkeiten offen.',
 'Career orientation compares freely selected personal interests/strengths with concrete demands of entrepreneurship and employment. Skills can develop; personality lists prove neither fitness/unfitness nor later success. A justified exploration step keeps options open.',
 'Die Person vergleicht ausgewählte eigene Interessen/Stärken mit Anforderungen an Unternehmer- und Beschäftigtenrollen anhand neuer Tätigkeitsprofile, benennt Passungen und Entwicklungsbedarf und leitet begründete nächste Erkundungsschritte ohne starres Eignungsurteil ab.',
 'The learner compares selected personal interests/strengths with demands in entrepreneurial and employee roles using new task profiles, identifies matches/development needs and derives justified exploration steps without a rigid fitness verdict.',
 [('repair-enterprise-and-employed-team','Vergleiche anhand bereitgestellter fiktiver Profile eine selbstständige Reparaturdienstleistung mit einer Beschäftigtenrolle im Reparaturteam: Auftragsklärung, sichere fachliche Arbeit und Kooperation sind beiden gemeinsam; die Gründung umfasst zusätzlich Planung, Finanzierung und Verantwortung für den Betrieb. Wähle eigene Interessen/Stärken, die du nennen möchtest, und begründe einen Erkundungsschritt.',
   'Use provided fictional profiles to compare self-employed repair work with an employee role in a repair team. Both need order clarification, safe skilled work and cooperation; entrepreneurship additionally involves planning, finance and responsibility for the business. Select interests/strengths you wish to mention and justify an exploration step.',
   'Die Person vergleicht gemeinsame und unterschiedliche Anforderungen mit ihren gewählten Interessen/Stärken, nennt eine passende Tätigkeit und einen entwickelbaren Bereich und begründet etwa Berufsgespräch oder Erkundung beider Rollen. Sie vermeidet Gleichsetzungen wie kreativ=geeignet, zurückhaltend=ungeeignet oder Interesse=nachgewiesene Fachkompetenz.',
   'The learner compares shared/distinct requirements with selected personal interests/strengths, identifies a matching task and a developable area and justifies e.g. a career conversation or exploration of both roles, avoiding creativity=fit, quiet=unfit or interest=proven competence.',
   'Gemeinsame fachliche Anforderungen mit zusätzlicher Gründungsverantwortung.','Shared skilled demands with additional entrepreneurial responsibilities.'),
  ('creative-digital-role-and-changing-interest','Andere bereitgestellte fiktive Profile beschreiben eine angestellte digitale Gestaltungsrolle mit Kundengesprächen und Fristen sowie eine eigene kleine Gestaltungsagentur mit zusätzlicher Akquise, Kalkulation und Teamkoordination. Wähle ein für dich interessantes Tätigkeitsfeld, vergleiche eigene Stärken/Interessen mit beiden Rollen und überprüfe die Orientierung unter neu entdecktem Interesse an Teamorganisation.',
   'Other provided fictional profiles describe an employed digital design role with client conversations/deadlines and a small own agency adding customer acquisition, costing and team coordination. Choose an interesting field, compare your interests/strengths with both roles and reconsider orientation after discovering an interest in team organisation.',
   'Die Person begründet eine vorläufige Orientierung aus Tätigkeitsanforderungen und freiwillig gewählten eigenen Bezugspunkten, prüft Organisation als gemeinsame beziehungsweise zusätzliche Anforderung und passt einen Erkundungs-/Entwicklungsschritt nachvollziehbar an. Sie behandelt die neue Information als Anlass zur offenen Erkundung statt endgültiger Berufszuweisung.',
   'The learner justifies tentative orientation using job demands and freely selected personal points, checks organisation as a shared/additional demand and adapts an exploration/development step, treating new information as a prompt for open exploration rather than a definitive career assignment.',
   'Geändertes Interesse prüft eine begründete vorläufige Orientierung.','A changed interest tests justified tentative orientation.')],
 [('role','Selbstständigkeit und Beschäftigung in zwei unterschiedlichen Tätigkeitsfeldern.','Entrepreneurship and employment in two different fields.'),('reflection','Eigene ausgewählte Interessen, Stärken und entwickelbare Fähigkeiten.','Selected personal interests, strengths and developable skills.')])
add('Analyse the business landscape using data','The learner can analyse Germany\'s business landscape using quantitative data, create charts in a spreadsheet and draw conclusions for career and business decisions.','data',
 'Die deutsche Unternehmenslandschaft lässt sich anhand datierter amtlicher Tabellen vergleichen, wenn Einheit, Abgrenzung, Jahr und Maßstab erkennbar sind. Unternehmenszahl und Beschäftigtenzahl beantworten verschiedene Fragen; Diagramme und abgeleitete Mittelwerte begründen begrenzte Berufs-/Unternehmensüberlegungen, nicht persönliche Erfolgsgarantien oder ungeprüfte Zeitvergleiche.',
 'Dated official tables support comparisons of Germany\'s business landscape when units, definitions, year and scale are explicit. Company and employee counts answer different questions; charts/derived means support bounded career/business considerations rather than personal guarantees or unchecked comparisons over time.',
 'Die Person analysiert neue datierte amtliche Unternehmensdaten mit überprüfbaren Tabellenkalkulationsgrafiken und Berechnungen, unterscheidet Zähl-/Beschäftigungsmaße und Datenabgrenzungen und leitet begrenzte Berufs-/Unternehmensschlüsse samt offenen Informationsfragen ab.',
 'The learner analyses new dated official company data with checkable spreadsheet charts/calculations, distinguishes company/employment measures and definitions and derives bounded career/business implications with remaining information questions.',
 [('official-2023-sector-counts','Bearbeite die bereitgestellte Destatis-Originaltabelle Unternehmen und abhängig Beschäftigte nach Wirtschaftsabschnitten, Berichtsjahr2023, Stand4.August2025, mit Fußnoten. Auszug: VerarbeitendesGewerbe201453Unternehmen/7601361Beschäftigte; Handel543301/5489308. Erstelle getrennte beschriftete Tabellenkalkulationsdiagramme und rechne Beschäftigte je Unternehmen. Ziehe begrenzte Schlüsse für eine Berufserkundung oder Geschäftsidee.',
   'Use the provided original Destatis table on companies/dependent employees by sector, reporting year2023, updated4August2025, including footnotes. Extract: manufacturing201453companies/7601361employees; retail543301/5489308. Create separate labelled spreadsheet charts and compute employees per company. Draw bounded implications for career exploration or a business idea.',
   'Die Person stellt mehr Handelsunternehmen, aber mehr Beschäftigte im verarbeitenden Gewerbe dar, berechnet rund37,73 gegenüber10,10 Beschäftigten je Unternehmen und erklärt den Mittelwert mit der amtlichen Unternehmensabgrenzung. Sie leitet einen begründeten Erkundungsbedarf ab, nicht die Größe eines typischen Betriebs oder individuelle Einstellungs-/Gründungschancen aus Aggregaten.',
   'The learner shows more retail companies but more manufacturing employees, calculates approximately37.73versus10.10employees per company and explains the mean using the official company definition. They derive a justified exploration need rather than typical establishment size or individual employment/start-up chances from aggregates.',
   'Reale datierte Branchenzahlen mit verschiedenen Nennern.','Real dated sector counts with different denominators.'),
  ('official-2024-craft-structure','Nutze eine zweite bereitgestellte Destatis-Originaltabelle Handwerk: Unternehmen, Beschäftigte und Umsatz2024, Stand23.April2026, mit Abgrenzung und Rundung. Gerundete Unternehmenszahlen in Tausend: VerarbeitendesGewerbe insgesamt210/Handwerk86; Bau388/Handwerk253. Berechne Anteile und erstelle ein zielgruppenpassendes Tabellenkalkulationsdiagramm für eine Berufsorientierungsgruppe; beurteile einen möglichen Einstieg in ein handwerkliches Feld.',
   'Use a second provided original Destatis craft table: companies/employees/revenue2024, updated23April2026, with definitions/rounding. Rounded company counts in thousands: manufacturing total210/craft86; construction388/craft253. Compute shares and create an audience-suited spreadsheet chart for career orientation; consider a possible entry into a craft field.',
   'Die Person berechnet aus gerundeten Zahlen ungefähr41% beziehungsweise65,2%, erklärt Rundungsabweichungen zu veröffentlichten Anteilen und stellt Anteile mit gleichem Bezugsmaß dar. Sie leitet gezielte Fragen zu Tätigkeiten, Qualifikation und örtlichen Möglichkeiten ab, unterscheidet Anzahlanteil von Beschäftigungsanteil und vergleicht nicht unbesehen andere statistische Einheiten oder Jahre.',
   'The learner calculates approximately41%and65.2%from rounded counts, explains rounding differences from published shares and charts shares on the same basis. They derive targeted questions on tasks, qualifications and local options, distinguish company/employment shares and avoid unchecked comparisons across statistical units or years.',
   'Neue Handwerksabgrenzung und gerundete Anteile statt bloßer Wiederholung.','A new craft definition and rounded shares rather than repeating counts.')],
 [('definition','Amtlich abgegrenzte Unternehmen2023 versus rechtliche Einheiten/Handwerk2024.','Officially defined companies2023 versus legal units/craft2024.'),('measure','Anzahl, Beschäftigte je Unternehmen und Handwerksanteil.','Counts, employees per company and craft shares.')])
add('Evaluate changes in the world of work','The learner can evaluate opportunities and risks of current changes in the world of work and derive implications for their own career orientation.','concept',
 'Aktuelle Arbeitsweltentwicklungen werden mit datierten belastbaren Materialien und konkreten Tätigkeitsbedingungen beurteilt. Neue Technik oder flexible Arbeit kann Ressourcen und Belastungen zugleich verändern; Folgen hängen von Gestaltung, Tätigkeit und Betroffenen ab. Eigene Berufsorientierung bleibt eine begründete offene Entscheidung, keine Vorhersage.',
 'Current changes at work are evaluated using dated reliable materials and concrete task conditions. New technology/flexible work can change resources and strain together; effects depend on design, activity and people affected. Personal career orientation remains a justified open decision, not a prediction.',
 'Die Person beurteilt neue aktuelle, datiert belegte Entwicklungen der Arbeitswelt mit benannten Chancen/Risiken und Bedingungen, berücksichtigt unterschiedliche Tätigkeiten und leitet begründete Konsequenzen für eigene berufliche Erkundung oder Kompetenzentwicklung ab.',
 'The learner evaluates new current changes using dated evidence, names opportunities/risks and conditions, considers different tasks and derives justified implications for personal career exploration or skills development.',
 [('digital-assistance-and-task-design','Nutze bereitgestelltes datiertes BAuA-Primärmaterial zur Digitalisierung/KI in der Arbeitswelt, einschließlich Erhebungsjahr und Grenzen. Der ergänzende fiktive Fall vergleicht digitale Assistenz im Kundenservice: entlastende Informationssuche, aber zusätzliche parallele Anfragen und unverändert nötige menschliche Fehlerprüfung. Beurteile Chancen/Risiken und leite einen eigenen Erkundungs- oder Lernschritt ab.',
   'Use provided dated primary BAuA material on digitalisation/AI at work, including study year/limits. An accompanying fictional case compares digital assistance in customer service: easier information retrieval but more simultaneous enquiries and continued human error checking. Evaluate opportunities/risks and derive a personal exploration or learning step.',
   'Die Person unterscheidet empirisch belegte Aussagen von Fallannahmen, wägt Entlastung, Handlungsspielraum, Intensivierung und Fehlerverantwortung unter konkreter Gestaltung ab und vermeidet pauschale Jobverlust-/Erfolgsvorhersagen. Sie begründet etwa Erkundung tatsächlicher Aufgaben und Entwicklung fachlicher Prüf-/Kooperationskompetenz für ihre gewählte Orientierung.',
   'The learner separates empirical evidence from case assumptions, weighs relief, autonomy, intensification and error responsibility under concrete design and avoids blanket job-loss/success predictions. They justify e.g. exploring actual tasks and developing domain checking/cooperation skills for their chosen orientation.',
   'Technische Entlastung und neue Belastung können gleichzeitig bestehen.','Technical relief and new strain can coexist.'),
  ('hybrid-and-onsite-work','Nutze anderes bereitgestelltes datiertes BAuA-Primärmaterial zu mobiler Arbeit/Erreichbarkeit. Ein fiktiver Entwicklungsbetrieb bietet hybride Bildschirmarbeit mit vereinbarten Kontaktzeiten, während seine Produktionsarbeit vor Ort stattfinden muss; Grenzen können bei ständigen Nachrichten verschwimmen. Beurteile Chancen und Risiken für beide Tätigkeiten und leite Konsequenzen für eine von dir gewählte berufliche Orientierung ab.',
   'Use other provided dated primary BAuA material on mobile work/reachability. A fictional development firm offers hybrid screen work with agreed contact times, while production must be on site; constant messages can blur boundaries. Evaluate opportunities/risks for both tasks and derive implications for a career direction you choose.',
   'Die Person wägt Flexibilität/Pendelentlastung gegen Abgrenzungs-, Kooperations- und Zugangsprobleme ab, berücksichtigt ungleiche Tätigkeitsmöglichkeiten und konkrete Kontaktregeln. Sie begründet für eigene Orientierung Fragen zu Arbeitsbedingungen und Kompetenzen, statt mobile Arbeit generell besser zu nennen oder einzelne Fallbedingungen als gesamtdeutschen Trend auszugeben.',
   'The learner weighs flexibility/less commuting against boundary, cooperation and access problems, considers unequal task possibilities and concrete contact rules and derives personal questions on conditions/skills rather than declaring mobile work universally better or generalising one case to Germany.',
   'Arbeitsform und ungleiche Tätigkeitsbedingungen als eigenständiger Transfer.','Work form and unequal task conditions as an independent transfer.')],
 [('change','Digitale Assistenz versus hybride/moblie Arbeitsorganisation.','Digital assistance versus hybrid/mobile organisation.'),('condition','Erhebungsgrenzen, Tätigkeitsunterschiede und konkrete Gestaltung.','Study limits, task differences and concrete design.')])
add('Evaluate government conditions affecting businesses','The learner can evaluate how government conditions influence entrepreneurial action.','concept',
 'Staatliche Regeln, Infrastruktur und Förderung verändern Handlungsbedingungen über Kosten, Möglichkeiten, Sicherheit und Anreize. Beurteilung nennt Mechanismus, Perspektive, Zielkonflikt und fallbezogene Bedingungen; reale Rechtsbehauptungen verlangen aktuell datierte bereitgestellte Regeln, während Modellregeln als solche erkennbar bleiben.',
 'Government rules, infrastructure and support change business conditions through costs, opportunities, security and incentives. Evaluation specifies mechanism, perspective, trade-offs and case conditions; claims about actual law require current dated provided rules and model rules remain labelled.',
 'Die Person beurteilt in neuen Fällen staatliche Rahmenbedingungen anhand nachvollziehbarer Wirkungswege, betrieblicher Handlungsmöglichkeiten und öffentlicher Ziele, wägt Nutzen/Kosten und Alternativen unter benannten Bedingungen ab und trennt tatsächliche datierte Regeln von fiktiven Modellannahmen.',
 'In new cases, the learner evaluates government conditions using clear mechanisms, business options and public goals, weighs benefits/costs and alternatives under explicit conditions and distinguishes dated actual rules from fictional model assumptions.',
 [('fictional-emission-standard','Eine ausdrücklich fiktive Modellregel verlangt ab dem Folgejahr einen Filter. Für einen Betrieb: Investition10000, jährliche laufende Mehrkosten500, vermiedene lokale Emissionen; eine alternative Prozessänderung kostet12000 und spart jährlich300 an Betriebsmitteln. Beurteile Handlungsbedingungen und Optionen ohne diese Modellbeträge als deutsches Recht auszugeben.',
   'An explicitly fictional model rule requires a filter from next year. For a firm: investment10000, annual extra running costs500, avoided local emissions; an alternative process change costs12000 and saves300 annually in inputs. Evaluate business conditions/options without presenting these amounts as German law.',
   'Die Person erklärt verbindlichen Mindeststandard, Investitions-/Finanzierungsbedarf und öffentliche Umweltziele, vergleicht filterbezogene Folgekosten mit der teureren, laufend sparenden Alternative und benennt Zeithorizont/Kapazität als Beurteilungsbedingungen. Sie begründet ein bedingtes Urteil ohne pauschal Regeln als nur Last oder jeden Umweltgewinn als automatisch rentabel zu werten.',
   'The learner explains a binding minimum, investment/financing needs and public environmental goals, compares filter running costs with the costlier input-saving alternative and specifies time horizon/capacity, giving a conditional judgement without equating rules only with burden or every environmental benefit with profitability.',
   'Standard verändert technische Wahl und Finanzierung mit öffentlichem Ziel.','A standard changes technology choice/finance with a public goal.'),
  ('infrastructure-and-conditional-support','Ein anderer fiktiver Modellfall bietet einem kleinen Betrieb Breitband-Infrastruktur und einen Zuschuss4000 zu einer Weiterbildung6000, sofern Arbeitszeit für Training bereitgestellt wird. Ohne Training wären2000 Euro unmittelbar für Werbung verfügbar; Wirkungen sind unsicher. Beurteile staatlichen Einfluss und begründe eine bedingte unternehmerische Entscheidung.',
   'Another fictional model case offers a small firm broadband infrastructure and a4000grant toward6000training, conditional on allocating work time. Without training,2000would be immediately available for advertising; effects are uncertain. Evaluate government influence and justify a conditional business decision.',
   'Die Person erklärt Ermöglichung durch Infrastruktur und relative Preissenkung des Trainings auf2000 Eigenanteil, berücksichtigt Zeit-/Opportunitätskosten, Bedingungen und öffentliches Qualifikationsziel. Sie vergleicht Alternativen anhand des betrieblichen Bedarfs und verlangt Wirkungsprüfung statt Förderung mit sicherem Zusatzgewinn oder Zwang gleichzusetzen.',
   'The learner explains infrastructure enabling activity and a relative training cost reduction to2000own contribution, considers time/opportunity costs, conditions and public skills goals and compares options against business needs without equating support with guaranteed extra profit or coercion.',
   'Ermöglichende Infrastruktur und bedingter Anreiz statt erneuter Verbotsfall.','Enabling infrastructure and a conditional incentive rather than another prohibition.')],
 [('instrument','Verbindlicher Standard versus Infrastruktur und Förderung.','Binding standard versus infrastructure and support.'),('evaluation','Private Kosten/Chancen und öffentliche Umwelt-/Qualifikationsziele.','Private costs/opportunities and public environmental/skills goals.')])
add('Evaluate business action from stakeholder perspectives','The learner can evaluate business action from different stakeholder perspectives, including social responsibility and businesses\' significance for the economy and society.','concept',
 'Unternehmerisches Handeln berührt Eigentümer, Beschäftigte, Kundschaft, Lieferanten und gesellschaftliche Gruppen mit teils konkurrierenden Interessen. Bewertung verbindet diese Perspektiven mit Wertschöpfung, Beschäftigung, Versorgung und gesellschaftlicher Verantwortung; Gewinn allein oder bloße Absichtserklärungen reichen als umfassendes Urteil nicht.',
 'Business action affects owners, employees, customers, suppliers and social groups with sometimes competing interests. Evaluation connects these perspectives to value creation, jobs, supply and social responsibility; profit alone or statements of intent do not establish a comprehensive judgement.',
 'Die Person bewertet neue unternehmerische Entscheidungen aus mehreren konkret betroffenen Stakeholder-Perspektiven, erklärt Bedeutung für Wirtschaft/Gesellschaft und Verantwortung, wägt Zielkonflikte ab und begründet bedingte Handlungsvorschläge anhand überprüfbarer Kriterien.',
 'The learner evaluates new business decisions from several affected stakeholder perspectives, explains economic/social significance and responsibility, weighs trade-offs and justifies conditional options using checkable criteria.',
 [('automation-with-development-options','Ein fiktiver Betrieb plant Automatisierung: geringere Stückkosten, neue Wartungsaufgaben, aber Wegfall einfacher Tätigkeiten. Kunden hoffen auf günstigere Produkte, Eigentümer auf Ertrag, Beschäftigte auf sichere Arbeit; die Kommune interessiert sich für lokale Beschäftigung und Versorgung. Bewerte den Plan samt einer angebotenen Qualifizierung, deren Umfang und Stellenzahl noch nicht feststehen.',
   'A fictional firm plans automation: lower unit costs, new maintenance tasks but loss of simple tasks. Customers hope for lower prices, owners for returns, workers for secure jobs and the municipality for local employment/supply. Evaluate the plan and offered retraining whose scope/job numbers remain unknown.',
   'Die Person erläutert Vorteile und Risiken aus mindestens Eigentümer-, Beschäftigten-, Kunden- und gesellschaftlicher Perspektive, verbindet Produktivität/Versorgung/Beschäftigung und soziale Verantwortung und begründet Bedingungen etwa tragfähige Qualifizierung, Übergänge und überprüfbare Stellen-/Preiszusagen. Sie behauptet weder automatische Preissenkung noch dass Qualifizierung alle Verluste sicher ausgleicht.',
   'The learner explains benefits/risks from owner, worker, customer and societal perspectives, connects productivity/supply/jobs with responsibility and justifies conditions such as viable retraining, transitions and checkable job/price commitments, without assuming prices fall or retraining fully offsets losses.',
   'Produktivitätschance und Verteilungs-/Übergangskonflikt.','Productivity opportunities with distribution/transition trade-offs.'),
  ('supplier-cost-and-environmental-conditions','Ein anderer fiktiver Lebensmittelbetrieb kann zu billigerer Verpackung wechseln. Vorgegebene Fallinformationen nennen10% niedrigere Einkaufskosten, geringere Wiederverwertbarkeit und einen Lieferantenwechsel; tatsächliche Auswirkungen auf Preise, regionale Aufträge und Abfall müssen geprüft werden. Bewerte den Wechsel aus Stakeholder-Sicht und entwirf ein begründetes bedingtes Vorgehen.',
   'Another fictional food firm can switch to cheaper packaging. Case information gives10%lower purchasing costs, reduced recyclability and a supplier change; actual price, regional-contract and waste effects need checking. Evaluate from stakeholder perspectives and develop a justified conditional approach.',
   'Die Person berücksichtigt Eigentümer, Kundschaft, bisherige/neue Lieferanten und vom Abfall betroffene Gesellschaft, trennt eingesparte Verpackungskosten von unbekannten Gesamt-/Endpreiseffekten und verbindet Versorgung/Wertschöpfung mit Umweltverantwortung. Sie begründet etwa Alternativenvergleich und überprüfbare Abfall-/Kostenkriterien statt pauschal billig oder grün als Gesamturteil zu verwenden.',
   'The learner considers owners, customers, old/new suppliers and waste-affected society, distinguishes packaging savings from unknown total/retail-price effects, links supply/value creation with environmental responsibility and justifies e.g. comparing options against checkable waste/cost criteria instead of a blanket cheap/green verdict.',
   'Lieferketten- und Umweltperspektive mit offenem Gesamtkosteneffekt.','Supply-chain/environmental perspectives with unknown total-cost effects.')],
 [('decision','Automatisierung versus Verpackungs-/Lieferantenwechsel.','Automation versus packaging/supplier changes.'),('stakeholder','Beschäftigung, Kundenversorgung, Lieferanten, Umwelt und Eigentümer.','Jobs, customer supply, suppliers, environment and owners.')])
if __name__ == '__main__':
    m.main()
